    {
      "id": "r:3493499544",
      "kind": "approach",
      "harm": "relying on external IPC clients rather than internal FIFO eviction to free template memory could lead to node OOM",
      "quote": "Delegating template eviction responsibility to the client can put us in a situation where they handle it poorly and cause us to OOM",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:3563799563",
        "c:3570105870"
      ],
      "fix_pushed": false,
      "settled_by_id": "c:3570105870",
      "settled_by_quote": "In the scenario where they handle it poorly, we can use FIFO deletion. All `getMemoryLoad()` does is give clients an opportunity to handle it better. If they're fine with FIFO, then they never have to call this method."
    },
    {
      "id": "rc:2590041765",
      "kind": "safety",
      "harm": "template_tx_refs map accessed across multiple threads without synchronization creates data race hazards",
      "quote": "This map can updated from multiple threads, so it needs a mutex to be used safely.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "rc:2592303231"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:2592303231",
      "settled_by_quote": "To limit the scope of this PR, I only added the mutex, but called it `template_state_mutex` in anticipation."
    },
    {
      "id": "rc:3100806462",
      "kind": "style",
      "harm": "",
